package com.phonoodlesramen.actioncenter.ui.theme

import androidx.compose.ui.graphics.Color
import androidx.compose.ui.graphics.SolidColor
import androidx.compose.ui.graphics.vector.ImageVector
import androidx.compose.ui.graphics.vector.PathParser
import androidx.compose.ui.unit.dp

/*
 * The app's icons are Google's Material Symbols Rounded, weight 400, grade 0, 24 px
 * (github.com/google/material-design-icons, Apache License 2.0; see docs/third-party-notices.md).
 * Each path is copied as is from symbols/web/<name>/materialsymbolsrounded/<name>_24px.svg
 * (outlined) or <name>_fill1_24px.svg (filled: the constant ends in _FILL).
 *
 * To add one: copy that SVG's one `<path d>` into a constant named after the symbol and build it
 * with [symbol]. The SVGs draw in a `0 -960 960 960` viewBox, so [symbol] moves the path down by
 * 960 into a 960-unit box drawn at 24 dp. The few SVGs the repo still has in the older 24-unit
 * form (no viewBox, like auto_awesome) go through [symbol24] instead.
 */

/** The home's icons, and the settings', guide's and player's shared ones. */
object AppIcons {
    val Play = symbol("Play", PLAY_ARROW_FILL)
    val Spark = symbol24("Spark", AUTO_AWESOME_FILL)
    val Gear = symbol("Gear", SETTINGS_FILL)
    /** All apps. */
    val Grid = symbol("Grid", APPS)
    /** The full guide. */
    val Guide = symbol("Guide", VIEW_TIMELINE)
    /** Choose art. */
    val Art = symbol("Art", IMAGE)
    /** Reload, try again, remake, a new code. */
    val Restart = symbol("Restart", REFRESH)
    /** Start a program or an episode over. */
    val StartOver = symbol("StartOver", REPLAY)
    val Sync = symbol("Sync", SYNC)
    val Check = symbol("Check", CHECK)
    val Close = symbol("Close", CLOSE)
    val Hide = symbol("Hide", VISIBILITY_OFF)
    val Show = symbol("Show", VISIBILITY)
    val Info = symbol("Info", INFO)
    val Tv = symbol("Tv", TV)
    /** Watch in Plezy or Plex, and Open in Plezy or Plex: carrying on in another app (Phase 11). */
    val OpenIn = symbol("OpenIn", OPEN_IN_NEW)
    val Warning = symbol("Warning", WARNING_FILL)
    val Person = symbol("Person", PERSON_FILL)
    val AddPerson = symbol("AddPerson", PERSON_ADD_FILL)
    /** A channel carried up or down the list, or along the Live row. */
    val Move = symbol("Move", SWAP_VERT)
    /** A favorite channel (Phase 13): on its Live card, its guide row, and Add or Remove. */
    val Star = symbol("Star", STAR_FILL)
    /** Not your team yet: ☆ Make it your team (Phase 13, F5). */
    val StarOutline = symbol("StarOutline", STAR)
    /** The NFL (Phase 13): the row's All games card and the NFL screen's header. */
    val Football = symbol("Football", SPORTS_FOOTBALL_FILL)
    val Search = symbol("Search", SEARCH)
    /** The lens card's Back (Phase 14, L3): the title it showed before. */
    val Back = symbol("Back", ARROW_BACK)
    val Place = symbol("Place", LOCATION_ON_FILL)
    /** The die (the top bar's tray): Roll again. The top bar draws its own, so its face can change (`ui/dice/DieArt.kt`). */
    val Die = symbol("Die", CASINO_FILL)

    // Weather (top bar): one icon per sky family in weather.WeatherCodes.
    val Sun = symbol("Sun", CLEAR_DAY_FILL)
    val Moon = symbol("Moon", CLEAR_NIGHT_FILL)
    val Cloud = symbol("Cloud", CLOUD_FILL)
    val PartlyCloudy = symbol("PartlyCloudy", PARTLY_CLOUDY_DAY_FILL)
    val PartlyCloudyNight = symbol("PartlyCloudyNight", PARTLY_CLOUDY_NIGHT_FILL)
    val Fog = symbol("Fog", FOGGY_FILL)
    // `rainy_light` is streaks with no cloud, out of step with the rest of the family.
    val Drizzle = symbol("Drizzle", RAINY_FILL)
    val Rain = symbol("Rain", RAINY_FILL)
    val Snow = symbol("Snow", WEATHER_SNOWY_FILL)
    val Thunder = symbol("Thunder", THUNDERSTORM_FILL)
}

/** The symbols' box: 960 units, drawn at 24 dp. */
internal const val SYMBOL_BOX = 960f

/** A Material Symbol from its SVG's path, drawn in `0 -960 960 960`: moved down by 960 into the box. */
internal fun symbol(name: String, pathData: String): ImageVector = vector(name, pathData, translationY = SYMBOL_BOX)

/** A Material Symbol from an SVG in the older 24-unit form: scaled by 40 into the same box. */
private fun symbol24(name: String, pathData: String): ImageVector = vector(name, pathData, scale = SYMBOL_BOX / 24f)

private fun vector(name: String, pathData: String, translationY: Float = 0f, scale: Float = 1f): ImageVector =
    ImageVector.Builder(name = name, defaultWidth = 24.dp, defaultHeight = 24.dp, viewportWidth = SYMBOL_BOX, viewportHeight = SYMBOL_BOX)
        .addGroup(scaleX = scale, scaleY = scale, translationY = translationY)
        .addPath(pathData = PathParser().parsePathString(pathData).toNodes(), fill = SolidColor(Color.Black))
        .clearGroup()
        .build()

